"""The OpenCode guard plugin: an ES module that asks ``wev hook pre-tool-use`` about bash calls.

Shape from docs/research/harness-opencode.md section 4: an async function receiving
``{directory, ...}`` and returning hooks; ``tool.execute.before`` throws to block. The
stdin/stdout contract is the one in ``harness_hooks``. Any failure to run or read the guard
throws (fail closed). The note shows no ``client`` log call, so a warning uses
``console.warn``.
"""

from __future__ import annotations

import json
from pathlib import Path

PLUGIN_TEMPLATE = """\
// wev guard plugin (generated by wev harness install; do not edit)
import { spawnSync } from "node:child_process";

const WEV = __WEV_PATH__;
const TIMEOUT_MS = 10000;

function ask(payload) {
  const run = spawnSync(WEV, ["hook", "pre-tool-use", "--harness", "opencode"], {
    input: JSON.stringify(payload),
    encoding: "utf8",
    shell: false,
    timeout: TIMEOUT_MS,
  });
  if (run.error) throw new Error(`wev guard could not run: ${run.error.message}`);
  if (run.status !== 0) throw new Error(`wev guard exited with ${run.status}`);
  const text = run.stdout.trim();
  if (text === "") return null;
  let answer;
  try {
    answer = JSON.parse(text);
  } catch {
    throw new Error("wev guard answered something that is not JSON");
  }
  if (answer === null || typeof answer !== "object") {
    throw new Error("wev guard answered JSON that is not an object");
  }
  return answer;
}

export const WevGuard = async ({ directory }) => ({
  "tool.execute.before": async (input, output) => {
    if (input.tool !== "bash") return;
    const answer = ask({ tool: input.tool, args: output.args, cwd: directory });
    if (answer === null) return;
    if (answer.decision === "deny") throw new Error(String(answer.reason || "denied by wev"));
    if (answer.decision !== "allow") throw new Error("wev guard gave an unknown decision");
    if (answer.reason) console.warn(answer.reason);
  },
});
"""


def render_plugin(wev_path: Path) -> str:
    return PLUGIN_TEMPLATE.replace("__WEV_PATH__", json.dumps(str(wev_path)))
